def search_movies(**_extra):
    import json, os, datetime, time, hashlib, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0236000" if __import__("os").path.isdir("./environment_mix/0236000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat()
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip().replace("Z", "+00:00")
            try:
                dt = datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        return None

    def _gen_id(prefix, vendor_prefix):
        # vendor_prefix examples: tmdb_req, tmdb_res, tmdb_mov, tmdb_use
        return f"{vendor_prefix}_{datetime.datetime.now(datetime.timezone.utc).strftime('%y%m%d%H%M%S')}_{hashlib.sha256((prefix + '|' + str(time.time_ns()) + '|' + uuid.uuid4().hex).encode('utf-8')).hexdigest()[:24]}"

    def _bucket_start(dt, bucket_type):
        if bucket_type == "minute":
            return dt.replace(second=0, microsecond=0)
        if bucket_type == "day":
            return dt.replace(hour=0, minute=0, second=0, microsecond=0)
        return None

    def _normalize_params(_tool_name):
        # Tool surface exposes empty object; normalization is stable empty dict
        return {}

    def _cache_key(tool_name, params_obj):
        payload = {"tool_name": tool_name, "parameters": params_obj}
        s = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _extract_movie_ids(obj):
        ids = []
        if isinstance(obj, dict):
            if isinstance(obj.get("results"), list):
                for it in obj["results"]:
                    if isinstance(it, dict):
                        mid = it.get("id")
                        if isinstance(mid, int) and mid > 0:
                            ids.append(mid)
        return ids

    def _upsert_movie_rows(movies_rows, now, payload):
        if not isinstance(payload, dict):
            return
        results = payload.get("results")
        if not isinstance(results, list):
            return
        now_iso = _iso(now)
        for it in results:
            if not isinstance(it, dict):
                continue
            tmdb_movie_id = it.get("id")
            if not (isinstance(tmdb_movie_id, int) and tmdb_movie_id > 0):
                continue

            vote_average = it.get("vote_average")
            if vote_average is not None and not isinstance(vote_average, (int, float)):
                vote_average = None
            if isinstance(vote_average, (int, float)) and (vote_average < 0 or vote_average > 10):
                continue  # enforce constraint

            vote_count = it.get("vote_count")
            if vote_count is not None and not isinstance(vote_count, int):
                vote_count = None
            if isinstance(vote_count, int) and vote_count < 0:
                continue  # enforce constraint

            popularity = it.get("popularity")
            if popularity is not None and not isinstance(popularity, (int, float)):
                popularity = None
            if isinstance(popularity, (int, float)) and popularity < 0:
                continue  # enforce constraint

            title = it.get("title") or it.get("name")
            if not isinstance(title, str) or not title.strip():
                continue

            # Parse release date if present (date-only -> midnight UTC)
            rd = it.get("release_date")
            rd_iso = None
            if isinstance(rd, str) and rd.strip():
                s = rd.strip()
                try:
                    if len(s) == 10 and s[4] == "-" and s[7] == "-":
                        dt = datetime.datetime.fromisoformat(s)
                        dt = dt.replace(tzinfo=datetime.timezone.utc)
                        rd_iso = dt.isoformat()
                    else:
                        dt = _parse_dt(s)
                        rd_iso = _iso(dt) if dt else None
                except Exception:
                    rd_iso = None

            existing = None
            for r in movies_rows:
                if isinstance(r, dict) and r.get("tmdb_movie_id") == tmdb_movie_id:
                    existing = r
                    break

            if existing:
                if existing.get("status") == "deleted":
                    # cannot transition out of deleted per lifecycle
                    continue
                existing["title"] = title
                existing["original_title"] = it.get("original_title") if isinstance(it.get("original_title"), str) else existing.get("original_title")
                existing["overview"] = it.get("overview") if isinstance(it.get("overview"), str) else existing.get("overview")
                existing["release_date"] = rd_iso if rd_iso is not None else existing.get("release_date")
                existing["language"] = it.get("original_language") if isinstance(it.get("original_language"), str) else existing.get("language")
                existing["popularity"] = popularity
                existing["vote_average"] = float(vote_average) if isinstance(vote_average, (int, float)) else None
                existing["vote_count"] = vote_count
                existing["poster_path"] = it.get("poster_path") if isinstance(it.get("poster_path"), str) else existing.get("poster_path")
                existing["backdrop_path"] = it.get("backdrop_path") if isinstance(it.get("backdrop_path"), str) else existing.get("backdrop_path")
                existing["adult"] = it.get("adult") if isinstance(it.get("adult"), bool) else existing.get("adult")
                existing["tmdb_last_fetched_at"] = now_iso
                existing["updated_at"] = now_iso
                # mark active if it had become stale (allowed stale->active)
                if existing.get("status") == "stale":
                    existing["status"] = "active"
            else:
                movies_rows.append({
                    "id": _gen_id("mov", "tmdb_mov"),
                    "tmdb_movie_id": tmdb_movie_id,
                    "title": title,
                    "original_title": it.get("original_title") if isinstance(it.get("original_title"), str) else None,
                    "overview": it.get("overview") if isinstance(it.get("overview"), str) else None,
                    "release_date": rd_iso,
                    "language": it.get("original_language") if isinstance(it.get("original_language"), str) else None,
                    "popularity": popularity,
                    "vote_average": float(vote_average) if isinstance(vote_average, (int, float)) else None,
                    "vote_count": vote_count,
                    "poster_path": it.get("poster_path") if isinstance(it.get("poster_path"), str) else None,
                    "backdrop_path": it.get("backdrop_path") if isinstance(it.get("backdrop_path"), str) else None,
                    "adult": it.get("adult") if isinstance(it.get("adult"), bool) else None,
                    "status": "active",
                    "tmdb_last_fetched_at": now_iso,
                    "created_at": now_iso,
                    "updated_at": now_iso,
                })

    def _ensure_request_row(tool_requests_rows, tool_name, api_key_id, now):
        now_iso = _iso(now)
        rid = _gen_id("req", "tmdb_req")
        row = {
            "id": rid,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "parameters": {},
            "status": "received",
            "http_status": None,
            "error_code": None,
            "error_message": None,
            "cache_mode": "bypass",
            "response_id": None,
            "started_at": None,
            "completed_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        tool_requests_rows.append(row)
        return row

    def _transition_tool_request(tr, to_status, now, http_status=None, error_code=None, error_message=None, cache_mode=None, response_id=None):
        # enforce lifecycle: received -> processing -> succeeded|failed
        allowed = {
            "received": {"processing", "failed"},
            "processing": {"succeeded", "failed"},
            "succeeded": set(),
            "failed": set(),
        }
        cur = tr.get("status")
        if cur not in allowed or to_status not in allowed[cur]:
            return False
        tr["status"] = to_status
        if to_status == "processing":
            tr["started_at"] = _iso(now)
        if to_status in ("succeeded", "failed"):
            tr["completed_at"] = _iso(now)
        if http_status is not None:
            tr["http_status"] = http_status
        if error_code is not None:
            tr["error_code"] = error_code
        if error_message is not None:
            tr["error_message"] = error_message
        if cache_mode is not None:
            tr["cache_mode"] = cache_mode
        if response_id is not None:
            tr["response_id"] = response_id
        tr["updated_at"] = _iso(now)
        return True

    def _auth_find_any_active_key(api_keys_rows):
        # Ambient auth: choose a key that can serve the call (active with valid quotas)
        for r in api_keys_rows:
            if not isinstance(r, dict):
                continue
            if r.get("status") != "active":
                continue
            qpm = r.get("quota_requests_per_minute")
            qpd = r.get("quota_requests_per_day")
            if not (isinstance(qpm, int) and isinstance(qpd, int) and qpm >= 0 and qpd >= 0):
                continue
            if r.get("plan") not in ("free", "pro", "internal"):
                continue
            return r
        return None

    def _check_and_increment_quota(buckets_rows, api_key_row, now):
        qpm = int(api_key_row.get("quota_requests_per_minute", 0))
        qpd = int(api_key_row.get("quota_requests_per_day", 0))
        now_iso = _iso(now)

        for bucket_type, quota in (("minute", qpm), ("day", qpd)):
            bs = _bucket_start(now, bucket_type)
            if bs is None:
                return _err("VALIDATION_ERROR", "Invalid bucket_type.")
            bs_iso = _iso(bs)
            existing = None
            for r in buckets_rows:
                if isinstance(r, dict) and r.get("api_key_id") == api_key_row["id"] and r.get("bucket_type") == bucket_type and r.get("bucket_start") == bs_iso:
                    existing = r
                    break
            cur = 0
            if existing:
                try:
                    cur = int(existing.get("request_count", 0))
                except Exception:
                    cur = 0
            if quota >= 0 and (cur + 1) > quota:
                # compute retry_after for minute bucket (best-effort)
                extra = {}
                if bucket_type == "minute":
                    retry_after = 60
                    if existing:
                        lra = _parse_dt(existing.get("last_request_at"))
                        if lra:
                            elapsed = (now - lra).total_seconds()
                            retry_after = max(1, int(60 - elapsed))
                    extra["retry_after_seconds"] = retry_after
                return _err("QUOTA_EXCEEDED", f"Rate limit exceeded for {bucket_type} bucket.", bucket_type=bucket_type, **extra)

        # upsert after checks pass
        for bucket_type in ("minute", "day"):
            bs_iso = _iso(_bucket_start(now, bucket_type))
            existing = None
            for r in buckets_rows:
                if isinstance(r, dict) and r.get("api_key_id") == api_key_row["id"] and r.get("bucket_type") == bucket_type and r.get("bucket_start") == bs_iso:
                    existing = r
                    break
            if existing:
                existing["request_count"] = int(existing.get("request_count", 0) or 0) + 1
                existing["last_request_at"] = now_iso
                existing["updated_at"] = now_iso
            else:
                buckets_rows.append({
                    "id": _gen_id("use", "tmdb_use"),
                    "api_key_id": api_key_row["id"],
                    "bucket_type": bucket_type,
                    "bucket_start": bs_iso,
                    "request_count": 1,
                    "last_request_at": now_iso,
                    "created_at": now_iso,
                    "updated_at": now_iso,
                })
        return None

    t0 = time.perf_counter()
    now = _utcnow()
    tool_name = "search_movies"
    normalized_params = _normalize_params(tool_name)
    ck = _cache_key(tool_name, normalized_params)

    api_keys = _load("api_keys.json")
    tool_requests = _load("tool_requests.json")
    tmdb_responses = _load("tmdb_responses.json")
    movies = _load("movies.json")
    buckets = _load("api_key_usage_buckets.json")

    api_key_row = _auth_find_any_active_key(api_keys)
    api_key_id = api_key_row["id"] if api_key_row else None

    # Always log the request
    tr = _ensure_request_row(tool_requests, tool_name, api_key_id, now)
    _save("tool_requests.json", tool_requests)

    # Move to processing
    _transition_tool_request(tr, "processing", now)
    _save("tool_requests.json", tool_requests)

    # Require a usable key (vendor behaviour for these tools)
    if not api_key_row:
        _transition_tool_request(
            tr, "failed", now,
            http_status=401,
            error_code="UNAUTHORIZED",
            error_message="Missing or invalid API key.",
            cache_mode="bypass",
            response_id=None,
        )
        _save("tool_requests.json", tool_requests)
        return _err("UNAUTHORIZED", "Missing or invalid API key.", request_id=tr["id"], latency_ms=int((time.perf_counter() - t0) * 1000))

    if api_key_row.get("status") != "active":
        _transition_tool_request(
            tr, "failed", now,
            http_status=403,
            error_code="KEY_FORBIDDEN",
            error_message="API key is not active.",
            cache_mode="bypass",
            response_id=None,
        )
        _save("tool_requests.json", tool_requests)
        return _err("UNAUTHORIZED", "API key is not active.", request_id=tr["id"], latency_ms=int((time.perf_counter() - t0) * 1000))

    quota_err = _check_and_increment_quota(buckets, api_key_row, now)
    if quota_err:
        _save("api_key_usage_buckets.json", buckets)
        _transition_tool_request(
            tr, "failed", now,
            http_status=429,
            error_code="QUOTA_EXCEEDED",
            error_message=quota_err["error"]["message"],
            cache_mode="bypass",
            response_id=None,
        )
        _save("tool_requests.json", tool_requests)
        return quota_err

    # persist usage increments and last_used_at (only on successful processing start)
    api_key_row["last_used_at"] = _iso(now)
    api_key_row["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)
    _save("api_key_usage_buckets.json", buckets)

    # Cache lookup
    cache_hit = None
    for r in tmdb_responses:
        if isinstance(r, dict) and r.get("tool_name") == tool_name and r.get("cache_key") == ck:
            cache_hit = r
            break

    # Stale on read if expired
    if cache_hit and cache_hit.get("status") == "fresh":
        exp = _parse_dt(cache_hit.get("expires_at"))
        if exp and now >= exp:
            # transition fresh->stale
            cache_hit["status"] = "stale"
            cache_hit["updated_at"] = _iso(now)
            _save("tmdb_responses.json", tmdb_responses)

    if cache_hit and cache_hit.get("status") == "fresh":
        _transition_tool_request(
            tr, "succeeded", now,
            http_status=200,
            error_code=None,
            error_message=None,
            cache_mode="hit",
            response_id=cache_hit.get("id"),
        )
        _save("tool_requests.json", tool_requests)
        payload = cache_hit.get("response_json") if isinstance(cache_hit.get("response_json"), dict) else {}
        return {
            "request_id": tr["id"],
            "cache": {"mode": "hit", "response_id": cache_hit.get("id")},
            "data": payload,
            "latency_ms": int((time.perf_counter() - t0) * 1000),
        }

    # Cache miss: serve best-effort by using any existing cached payload (even if stale) or create a placeholder.
    # This implementation is offline; it simulates an upstream fetch by reusing a stale entry if present, otherwise empty payload.
    source_payload = {}
    if cache_hit and isinstance(cache_hit.get("response_json"), dict):
        source_payload = cache_hit["response_json"]
    else:
        # attempt: reuse any other non-purged response for this tool to avoid NOT_FOUND
        for r in tmdb_responses:
            if isinstance(r, dict) and r.get("tool_name") == tool_name and r.get("status") in ("fresh", "stale") and isinstance(r.get("response_json"), dict):
                source_payload = r["response_json"]
                break

    # upsert tmdb_responses row for deterministic key
    ttl_seconds = 3600
    expires_at = now + datetime.timedelta(seconds=ttl_seconds)
    now_iso = _iso(now)
    resp_row = None
    for r in tmdb_responses:
        if isinstance(r, dict) and r.get("tool_name") == tool_name and r.get("cache_key") == ck:
            resp_row = r
            break
    movie_ids = _extract_movie_ids(source_payload)
    if resp_row:
        if resp_row.get("status") != "purged":
            resp_row["status"] = "fresh"
        resp_row["response_json"] = source_payload if isinstance(source_payload, dict) else {}
        resp_row["movie_tmdb_ids"] = movie_ids if movie_ids else []
        resp_row["source_url"] = resp_row.get("source_url")
        resp_row["fetched_at"] = now_iso
        resp_row["expires_at"] = _iso(expires_at)
        resp_row["updated_at"] = now_iso
    else:
        resp_row = {
            "id": _gen_id("res", "tmdb_res"),
            "tool_name": tool_name,
            "cache_key": ck,
            "source_url": None,
            "response_json": source_payload if isinstance(source_payload, dict) else {},
            "movie_tmdb_ids": movie_ids if movie_ids else [],
            "status": "fresh",
            "fetched_at": now_iso,
            "expires_at": _iso(expires_at),
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        tmdb_responses.append(resp_row)

    _upsert_movie_rows(movies, now, resp_row.get("response_json"))
    _save("movies.json", movies)
    _save("tmdb_responses.json", tmdb_responses)

    _transition_tool_request(
        tr, "succeeded", now,
        http_status=200,
        cache_mode="miss",
        response_id=resp_row.get("id"),
    )
    _save("tool_requests.json", tool_requests)

    return {
        "request_id": tr["id"],
        "cache": {"mode": "miss", "response_id": resp_row.get("id")},
        "data": resp_row.get("response_json") if isinstance(resp_row.get("response_json"), dict) else {},
        "latency_ms": int((time.perf_counter() - t0) * 1000),
    }

def get_recommendations(**_extra):
