                    break
            cur = 0
            if existing:
                try:
                    cur = int(existing.get("request_count", 0))
                except Exception:
                    cur = 0
            if quota >= 0 and (cur + 1) > quota:
                extra = {}
                if bucket_type == "minute":
                    retry_after = 60
                    if existing:
                        lra = _parse_dt(existing.get("last_request_at"))
                        if lra:
                            elapsed = (now - lra).total_seconds()
                            retry_after = max(1, int(60 - elapsed))
                    extra["retry_after_seconds"] = retry_after
                return _err("QUOTA_EXCEEDED", f"Rate limit exceeded for {bucket_type} bucket.", bucket_type=bucket_type, **extra)

        for bucket_type in ("minute", "day"):
            bs_iso = _iso(_bucket_start(now, bucket_type))
            existing = None
            for r in buckets_rows:
                if isinstance(r, dict) and r.get("api_key_id") == api_key_row["id"] and r.get("bucket_type") == bucket_type and r.get("bucket_start") == bs_iso:
                    existing = r
                    break
            if existing:
                existing["request_count"] = int(existing.get("request_count", 0) or 0) + 1
                existing["last_request_at"] = now_iso
                existing["updated_at"] = now_iso
            else:
                buckets_rows.append({
                    "id": _gen_id("use", "tmdb_use"),
                    "api_key_id": api_key_row["id"],
                    "bucket_type": bucket_type,
                    "bucket_start": bs_iso,
                    "request_count": 1,
                    "last_request_at": now_iso,
                    "created_at": now_iso,
                    "updated_at": now_iso,
                })
        return None

    # Tool surface exposes no parameters, so accept ambient call.
    # Resolve a movie id from existing cached context (best-effort): most recent tool_request for recommendations with response linkage,
    # else first movie_tmdb_id found in any stored recommendation response, else any cached movie id.
    t0 = time.perf_counter()
    now = _utcnow()
    tool_name = "get_recommendations"

    api_keys = _load("api_keys.json")
    tool_requests = _load("tool_requests.json")
    tmdb_responses = _load("tmdb_responses.json")
    movies = _load("movies.json")
    buckets = _load("api_key_usage_buckets.json")

    api_key_row = _auth_find_any_active_key(api_keys)
    api_key_id = api_key_row["id"] if api_key_row else None

    tr = _ensure_request_row(tool_requests, tool_name, api_key_id, now)
    _save("tool_requests.json", tool_requests)
    _transition_tool_request(tr, "processing", now)
    _save("tool_requests.json", tool_requests)

    if not api_key_row:
        _transition_tool_request(
            tr, "failed", now,
            http_status=401,
            error_code="UNAUTHORIZED",
            error_message="Missing or invalid API key.",
            cache_mode="bypass",
            response_id=None,
        )
        _save("tool_requests.json", tool_requests)
        return _err("UNAUTHORIZED", "Missing or invalid API key.", request_id=tr["id"], latency_ms=int((time.perf_counter() - t0) * 1000))

    quota_err = _check_and_increment_quota(buckets, api_key_row, now)
    if quota_err:
        _save("api_key_usage_buckets.json", buckets)
        _transition_tool_request(
            tr, "failed", now,
            http_status=429,
            error_code="QUOTA_EXCEEDED",
            error_message=quota_err["error"]["message"],
            cache_mode="bypass",
            response_id=None,
        )
        _save("tool_requests.json", tool_requests)
        return quota_err

    api_key_row["last_used_at"] = _iso(now)
    api_key_row["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)
    _save("api_key_usage_buckets.json", buckets)

    # Derive context movie id
    ctx_movie_id = None

    # 1) From newest recommendation response movie list (any)
    for r in reversed(tool_requests):
        if isinstance(r, dict) and r.get("tool_name") == tool_name:
            resp_id = r.get("response_id")
            if isinstance(resp_id, str):
                for rr in tmdb_responses:
                    if isinstance(rr, dict) and rr.get("id") == resp_id:
                        mids = rr.get("movie_tmdb_ids")
                        if isinstance(mids, list) and mids:
                            if isinstance(mids[0], int) and mids[0] > 0:
                                ctx_movie_id = mids[0]
                                break
                if ctx_movie_id:
                    break

    # 2) From any existing recommendation cached response_json.results[0].id
    if ctx_movie_id is None:
        for rr in tmdb_responses:
            if isinstance(rr, dict) and rr.get("tool_name") == tool_name and rr.get("status") in ("fresh", "stale"):
                mids = _extract_movie_ids(rr.get("response_json"))
                if mids:
                    ctx_movie_id = mids[0]
                    break

    # 3) From any cached movie row
    if ctx_movie_id is None:
        for m in movies:
            if isinstance(m, dict) and isinstance(m.get("tmdb_movie_id"), int) and m["tmdb_movie_id"] > 0 and m.get("status") != "deleted":
                ctx_movie_id = m["tmdb_movie_id"]
                break

    if ctx_movie_id is None:
        _transition_tool_request(
            tr, "failed", now,
            http_status=400,
            error_code="VALIDATION_ERROR",
            error_message="Missing required movie identifier (expected movie_id/tmdb_movie_id in call context).",
            cache_mode="bypass",
            response_id=None,
        )
        _save("tool_requests.json", tool_requests)
        return _err("VALIDATION_ERROR", "Missing required movie identifier (expected movie_id/tmdb_movie_id in call context).", http_status=400, request_id=tr["id"])

    normalized_params = {"tmdb_movie_id": ctx_movie_id}
    ck = _cache_key(tool_name, normalized_params)

    cache_hit = None
    for r in tmdb_responses:
        if isinstance(r, dict) and r.get("tool_name") == tool_name and r.get("cache_key") == ck:
            cache_hit = r
            break

    if cache_hit and cache_hit.get("status") == "fresh":
        exp = _parse_dt(cache_hit.get("expires_at"))
        if exp and now >= exp:
            cache_hit["status"] = "stale"
            cache_hit["updated_at"] = _iso(now)
            _save("tmdb_responses.json", tmdb_responses)

    if cache_hit and cache_hit.get("status") == "fresh":
        _transition_tool_request(
            tr, "succeeded", now,
            http_status=200,
            cache_mode="hit",
            response_id=cache_hit.get("id"),
        )
        _save("tool_requests.json", tool_requests)
        return {
            "request_id": tr["id"],
            "context": {"tmdb_movie_id": ctx_movie_id},
            "cache": {"mode": "hit", "response_id": cache_hit.get("id")},
            "data": cache_hit.get("response_json") if isinstance(cache_hit.get("response_json"), dict) else {},
            "latency_ms": int((time.perf_counter() - t0) * 1000),
        }

    # Offline miss: reuse any available recommendations payload for realism; otherwise empty dict.
    source_payload = {}
    if cache_hit and isinstance(cache_hit.get("response_json"), dict):
        source_payload = cache_hit["response_json"]
    else:
        for rr in tmdb_responses:
            if isinstance(rr, dict) and rr.get("tool_name") == tool_name and rr.get("status") in ("fresh", "stale") and isinstance(rr.get("response_json"), dict):
                source_payload = rr["response_json"]
                break

    ttl_seconds = 3600
    expires_at = now + datetime.timedelta(seconds=ttl_seconds)
    now_iso = _iso(now)
    resp_row = None
    for r in tmdb_responses:
        if isinstance(r, dict) and r.get("tool_name") == tool_name and r.get("cache_key") == ck:
            resp_row = r
            break
    movie_ids = _extract_movie_ids(source_payload)
    if resp_row:
        if resp_row.get("status") != "purged":
            resp_row["status"] = "fresh"
        resp_row["response_json"] = source_payload if isinstance(source_payload, dict) else {}
        resp_row["movie_tmdb_ids"] = movie_ids if movie_ids else []
        resp_row["source_url"] = resp_row.get("source_url")
        resp_row["fetched_at"] = now_iso
        resp_row["expires_at"] = _iso(expires_at)
        resp_row["updated_at"] = now_iso
    else:
        resp_row = {
            "id": _gen_id("res", "tmdb_res"),
            "tool_name": tool_name,
            "cache_key": ck,
            "source_url": None,
            "response_json": source_payload if isinstance(source_payload, dict) else {},
            "movie_tmdb_ids": movie_ids if movie_ids else [],
            "status": "fresh",
            "fetched_at": now_iso,
            "expires_at": _iso(expires_at),
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        tmdb_responses.append(resp_row)

    _save("tmdb_responses.json", tmdb_responses)

    _transition_tool_request(
        tr, "succeeded", now,
        http_status=200,
        cache_mode="miss",
        response_id=resp_row.get("id"),
    )
    _save("tool_requests.json", tool_requests)

    return {
        "request_id": tr["id"],
        "context": {"tmdb_movie_id": ctx_movie_id},
        "cache": {"mode": "miss", "response_id": resp_row.get("id")},
        "data": resp_row.get("response_json") if isinstance(resp_row.get("response_json"), dict) else {},
        "latency_ms": int((time.perf_counter() - t0) * 1000),
    }

def get_trending(**_extra):
    import json, os, datetime, time, hashlib, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0236000" if __import__("os").path.isdir("./environment_mix/0236000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat()
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip().replace("Z", "+00:00")
            try:
                dt = datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        return None

    def _gen_id(prefix, vendor_prefix):
        return f"{vendor_prefix}_{datetime.datetime.now(datetime.timezone.utc).strftime('%y%m%d%H%M%S')}_{hashlib.sha256((prefix + '|' + str(time.time_ns()) + '|' + uuid.uuid4().hex).encode('utf-8')).hexdigest()[:24]}"

    def _bucket_start(dt, bucket_type):
        if bucket_type == "minute":
            return dt.replace(second=0, microsecond=0)
        if bucket_type == "day":
            return dt.replace(hour=0, minute=0, second=0, microsecond=0)
        return None

    def _cache_key(tool_name, params_obj):
        payload = {"tool_name": tool_name, "parameters": params_obj}
        s = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _ensure_request_row(tool_requests_rows, tool_name, api_key_id, now):
        now_iso = _iso(now)
        rid = _gen_id("req", "tmdb_req")
        row = {
            "id": rid,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "parameters": {},
            "status": "received",
            "http_status": None,
            "error_code": None,
            "error_message": None,
            "cache_mode": "bypass",
            "response_id": None,
            "started_at": None,
            "completed_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        tool_requests_rows.append(row)
        return row

    def _transition_tool_request(tr, to_status, now, http_status=None, error_code=None, error_message=None, cache_mode=None, response_id=None):
        allowed = {
            "received": {"processing", "failed"},
            "processing": {"succeeded", "failed"},
            "succeeded": set(),
            "failed": set(),
        }
        cur = tr.get("status")
        if cur not in allowed or to_status not in allowed[cur]:
            return False
        tr["status"] = to_status
        if to_status == "processing":
            tr["started_at"] = _iso(now)
        if to_status in ("succeeded", "failed"):
            tr["completed_at"] = _iso(now)
        if http_status is not None:
            tr["http_status"] = http_status
        if error_code is not None:
            tr["error_code"] = error_code
        if error_message is not None:
            tr["error_message"] = error_message
        if cache_mode is not None:
            tr["cache_mode"] = cache_mode
        if response_id is not None:
            tr["response_id"] = response_id
        tr["updated_at"] = _iso(now)
        return True

    def _auth_find_any_active_key(api_keys_rows):
        for r in api_keys_rows:
            if not isinstance(r, dict):
                continue
            if r.get("status") != "active":
                continue
            qpm = r.get("quota_requests_per_minute")
            qpd = r.get("quota_requests_per_day")
            if not (isinstance(qpm, int) and isinstance(qpd, int) and qpm >= 0 and qpd >= 0):
                continue
            if r.get("plan") not in ("free", "pro", "internal"):
                continue
            return r
        return None

    def _check_and_increment_quota(buckets_rows, api_key_row, now):
        qpm = int(api_key_row.get("quota_requests_per_minute", 0))
        qpd = int(api_key_row.get("quota_requests_per_day", 0))
        now_iso = _iso(now)

        for bucket_type, quota in (("minute", qpm), ("day", qpd)):
            bs_iso = _iso(_bucket_start(now, bucket_type))
            existing = None
            for r in buckets_rows:
                if isinstance(r, dict) and r.get("api_key_id") == api_key_row["id"] and r.get("bucket_type") == bucket_type and r.get("bucket_start") == bs_iso:
                    existing = r
                    break
            cur = 0
            if existing:
                try:
                    cur = int(existing.get("request_count", 0))
                except Exception:
                    cur = 0
            if quota >= 0 and (cur + 1) > quota:
                extra = {}
                if bucket_type == "minute":
                    retry_after = 60
                    if existing:
                        lra = _parse_dt(existing.get("last_request_at"))
                        if lra:
                            elapsed = (now - lra).total_seconds()
                            retry_after = max(1, int(60 - elapsed))
                    extra["retry_after_seconds"] = retry_after
                return _err("QUOTA_EXCEEDED", f"Rate limit exceeded for {bucket_type} bucket.", bucket_type=bucket_type, **extra)

        for bucket_type in ("minute", "day"):
            bs_iso = _iso(_bucket_start(now, bucket_type))
            existing = None
            for r in buckets_rows:
                if isinstance(r, dict) and r.get("api_key_id") == api_key_row["id"] and r.get("bucket_type") == bucket_type and r.get("bucket_start") == bs_iso:
                    existing = r
                    break
            if existing:
                existing["request_count"] = int(existing.get("request_count", 0) or 0) + 1
                existing["last_request_at"] = now_iso
                existing["updated_at"] = now_iso
            else:
                buckets_rows.append({
                    "id": _gen_id("use", "tmdb_use"),
                    "api_key_id": api_key_row["id"],
                    "bucket_type": bucket_type,
                    "bucket_start": bs_iso,
                    "request_count": 1,
                    "last_request_at": now_iso,
                    "created_at": now_iso,
                    "updated_at": now_iso,
                })
        return None

    t0 = time.perf_counter()
    now = _utcnow()
    tool_name = "get_trending"

    api_keys = _load("api_keys.json")
    tool_requests = _load("tool_requests.json")
    tmdb_responses = _load("tmdb_responses.json")
    buckets = _load("api_key_usage_buckets.json")

    api_key_row = _auth_find_any_active_key(api_keys)
    api_key_id = api_key_row["id"] if api_key_row else None

    tr = _ensure_request_row(tool_requests, tool_name, api_key_id, now)
    _save("tool_requests.json", tool_requests)
    _transition_tool_request(tr, "processing", now)
    _save("tool_requests.json", tool_requests)

    if not api_key_row:
        _transition_tool_request(
            tr, "failed", now,
            http_status=401,
            error_code="UNAUTHORIZED",
            error_message="Missing or invalid API key.",
            cache_mode="bypass",
            response_id=None,
        )
        _save("tool_requests.json", tool_requests)
        return _err("UNAUTHORIZED", "Missing or invalid API key.", request_id=tr["id"], latency_ms=int((time.perf_counter() - t0) * 1000))

    quota_err = _check_and_increment_quota(buckets, api_key_row, now)
    if quota_err:
        _save("api_key_usage_buckets.json", buckets)
        _transition_tool_request(
            tr, "failed", now,
            http_status=429,
            error_code="QUOTA_EXCEEDED",
            error_message=quota_err["error"]["message"],
            cache_mode="bypass",
            response_id=None,
        )
        _save("tool_requests.json", tool_requests)
        return quota_err

    api_key_row["last_used_at"] = _iso(now)
    api_key_row["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)
    _save("api_key_usage_buckets.json", buckets)

    # Tool surface has no params; default time_window to "day" (TMDB supports day/week; vendor surface omitted).
    normalized_params = {"time_window": "day"}
    ck = _cache_key(tool_name, normalized_params)

    cache_hit = None
    for r in tmdb_responses:
        if isinstance(r, dict) and r.get("tool_name") == tool_name and r.get("cache_key") == ck:
            cache_hit = r
            break

    if cache_hit and cache_hit.get("status") == "fresh":
        exp = _parse_dt(cache_hit.get("expires_at"))
        if exp and now >= exp:
            cache_hit["status"] = "stale"
            cache_hit["updated_at"] = _iso(now)
            _save("tmdb_responses.json", tmdb_responses)

    if cache_hit and cache_hit.get("status") == "fresh":
        _transition_tool_request(
            tr, "succeeded", now,
            http_status=200,
            cache_mode="hit",
            response_id=cache_hit.get("id"),
        )
        _save("tool_requests.json", tool_requests)
        return {
            "request_id": tr["id"],
            "cache": {"mode": "hit", "response_id": cache_hit.get("id")},
            "data": cache_hit.get("response_json") if isinstance(cache_hit.get("response_json"), dict) else {},
            "latency_ms": int((time.perf_counter() - t0) * 1000),
        }

    # Offline miss: reuse any trending cached payload if present; otherwise empty.
    source_payload = {}
    if cache_hit and isinstance(cache_hit.get("response_json"), dict):
        source_payload = cache_hit["response_json"]
    else:
        for rr in tmdb_responses:
            if isinstance(rr, dict) and rr.get("tool_name") == tool_name and rr.get("status") in ("fresh", "stale") and isinstance(rr.get("response_json"), dict):
                source_payload = rr["response_json"]
                break

    ttl_seconds = 1800
    expires_at = now + datetime.timedelta(seconds=ttl_seconds)
    now_iso = _iso(now)

    resp_row = None
    for r in tmdb_responses:
        if isinstance(r, dict) and r.get("tool_name") == tool_name and r.get("cache_key") == ck:
            resp_row = r
            break

    if resp_row:
        if resp_row.get("status") != "purged":
            resp_row["status"] = "fresh"
        resp_row["response_json"] = source_payload if isinstance(source_payload, dict) else {}
        resp_row["movie_tmdb_ids"] = resp_row.get("movie_tmdb_ids") if isinstance(resp_row.get("movie_tmdb_ids"), list) else []
        resp_row["fetched_at"] = now_iso
        resp_row["expires_at"] = _iso(expires_at)
        resp_row["updated_at"] = now_iso
    else:
        resp_row = {
            "id": _gen_id("res", "tmdb_res"),
            "tool_name": tool_name,
            "cache_key": ck,
            "source_url": None,
            "response_json": source_payload if isinstance(source_payload, dict) else {},
            "movie_tmdb_ids": [],
            "status": "fresh",
            "fetched_at": now_iso,
            "expires_at": _iso(expires_at),
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        tmdb_responses.append(resp_row)

    _save("tmdb_responses.json", tmdb_responses)

    _transition_tool_request(
        tr, "succeeded", now,
        http_status=200,
        cache_mode="miss",
        response_id=resp_row.get("id"),
    )
    _save("tool_requests.json", tool_requests)

    return {
        "request_id": tr["id"],
        "cache": {"mode": "miss", "response_id": resp_row.get("id")},
        "data": resp_row.get("response_json") if isinstance(resp_row.get("response_json"), dict) else {},
        "latency_ms": int((time.perf_counter() - t0) * 1000),
    }

def list_tool_requests(api_key, api_key_id=None, tool_name=None, status=None, cache_mode=None, started_from=None, started_to=None, page=None, page_size=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0236000" if __import__("os").path.isdir("./environment_mix/0236000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if api_key_id is not None and (not isinstance(api_key_id, str) or not api_key_id.strip()):
        return _err("VALIDATION_ERROR", "api_key_id must be a non-empty string when provided.")
    if tool_name is not None and tool_name not in ("search_movies", "get_recommendations", "get_trending"):
        return _err("VALIDATION_ERROR", "Invalid tool_name.")
    if status is not None and status not in ("received", "processing", "succeeded", "failed"):
        return _err("VALIDATION_ERROR", "Invalid status.")
    if cache_mode is not None and cache_mode not in ("hit", "miss"):
        return _err("VALIDATION_ERROR", "Invalid cache_mode.")
    if page is None:
        page = 1
    if page_size is None:
        page_size = 25
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 100.")

    def _parse_dt(s, field_name):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field_name} must be an ISO date-time string.")
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field_name} must be an ISO date-time string.")

    dt_from, e = _parse_dt(started_from, "started_from")
    if e:
        return e
    dt_to, e = _parse_dt(started_to, "started_to")
    if e:
        return e
    if dt_from and dt_to and dt_to < dt_from:
        return _err("VALIDATION_ERROR", "started_to must be >= started_from.")

    api_keys = _load("api_keys.json")
    tool_requests = _load("tool_requests.json")

    # Authenticate: api_key may match api_keys.id OR api_keys.key_hash (client-visible value per contract)
    caller_key = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key or k.get("key_hash") == api_key:
            caller_key = k
            break

    # Log this list_tool_requests invocation into tool_requests store as closest allowed tool surface.
    # Since schema tool_name enum doesn't include list_tool_requests, we do not write an invalid row.
    # Instead, enforce auth and return results without logging to tool_requests (cannot satisfy schema enum).
    # If no valid caller_key, return unauthorized.
    if caller_key is None:
        return _err("UNAUTHORIZED", "Invalid API key.")
    if caller_key.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active.")

    # Filter rows
    def _row_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    rows = []
    for r in tool_requests:
        if not isinstance(r, dict):
            continue
        if api_key_id is not None and r.get("api_key_id") != api_key_id:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if status is not None and r.get("status") != status:
            continue
        if cache_mode is not None and r.get("cache_mode") != cache_mode:
            continue
        if dt_from is not None:
            sd = _row_dt(r.get("started_at"))
            if sd is None or sd < dt_from:
                continue
        if dt_to is not None:
            sd = _row_dt(r.get("started_at"))
            if sd is None or sd > dt_to:
                continue
        rows.append(r)

    # Newest-first by created_at then started_at
    def _sort_key(r):
        ca = _row_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        sa = _row_dt(r.get("started_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (ca, sa)

    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = rows[start:end]
    has_more = end < total

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "data": page_rows,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "latency_ms": latency_ms,
            "as_of": now_iso,
        },
    }

def get_tool_request(api_key, id, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0236000" if __import__("os").path.isdir("./environment_mix/0236000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat()
        return None

    def _gen_id(prefix):
        return f"{prefix}{int(time.time() * 1000)}_{os.getpid()}"

    def _hash_cache_key(tool_name, params_obj):
        payload = json.dumps({"tool_name": tool_name, "parameters": params_obj}, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(payload.encode("utf-8")).hexdigest()

    t0 = time.time()
    now = _utcnow()
    latency_ms = 0
    api_key_row = None
    tool_req_row = None
    http_status = None
    final_status = "failed"
    error_code = None
    error_message = None

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        latency_ms = int((time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.", latency_ms=latency_ms)
    if not isinstance(id, str) or not id.strip():
        latency_ms = int((time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", latency_ms=latency_ms)

    api_keys = _load("api_keys.json")
    if isinstance(api_keys, dict) and "rows" in api_keys:
        api_keys = api_keys["rows"]
    tool_requests = _load("tool_requests.json")
    if isinstance(tool_requests, dict) and "rows" in tool_requests:
        tool_requests = tool_requests["rows"]
    tmdb_responses = _load("tmdb_responses.json")
    if isinstance(tmdb_responses, dict) and "rows" in tmdb_responses:
        tmdb_responses = tmdb_responses["rows"]

    # Authenticate: accept key as api_keys.id (client-visible value in this store)
    for k in api_keys if isinstance(api_keys, list) else []:
        if isinstance(k, dict) and k.get("id") == api_key:
            api_key_row = k
            break
    if not api_key_row:
        # Record failed call even when unauthorized
        req_row = {
            "id": _gen_id("tmdb_req_"),
            "api_key_id": None,
            "tool_name": "search_movies",  # best-effort: schema requires enum; no exact tool for admin reads
            "parameters": {},
            "status": "failed",
            "http_status": 401,
            "error_code": "UNAUTHORIZED",
            "error_message": "Invalid API key.",
            "cache_mode": "bypass",
            "response_id": None,
            "started_at": _iso(now),
            "completed_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        try:
            tool_requests.append(req_row)
            _save("tool_requests.json", tool_requests)
        except Exception:
            pass
        latency_ms = int((time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "Invalid API key.", latency_ms=latency_ms)

    if api_key_row.get("status") != "active":
        # Record failed call
        req_row = {
            "id": _gen_id("tmdb_req_"),
            "api_key_id": api_key_row.get("id"),
            "tool_name": "search_movies",
            "parameters": {},
            "status": "failed",
            "http_status": 403,
            "error_code": "KEY_FORBIDDEN",
            "error_message": "API key is not active.",
            "cache_mode": "bypass",
            "response_id": None,
            "started_at": _iso(now),
            "completed_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        try:
            tool_requests.append(req_row)
            _save("tool_requests.json", tool_requests)
        except Exception:
            pass
        latency_ms = int((time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "API key is not active.", latency_ms=latency_ms)

    # Find tool request by id (do NOT assume id belongs to api_key)
    if isinstance(tool_requests, list):
        for r in tool_requests:
            if isinstance(r, dict) and r.get("id") == id:
                tool_req_row = r
                break

    if not tool_req_row:
        # Record call as succeeded (read executed) but returned 404 for missing entity
        req_row = {
            "id": _gen_id("tmdb_req_"),
            "api_key_id": api_key_row.get("id"),
            "tool_name": "search_movies",
            "parameters": {},
            "status": "failed",
            "http_status": 404,
            "error_code": "NOT_FOUND",
            "error_message": "tool_request not found.",
            "cache_mode": "bypass",
            "response_id": None,
            "started_at": _iso(now),
            "completed_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        try:
            tool_requests.append(req_row)
            _save("tool_requests.json", tool_requests)
        except Exception:
            pass
        latency_ms = int((time.time() - t0) * 1000)
        return _err("NOT_FOUND", "tool_request not found.", latency_ms=latency_ms)

    # Optionally hydrate response linkage (without erroring if missing)
    response_row = None
    rid = tool_req_row.get("response_id")
    if isinstance(rid, str) and rid:
        for tr in tmdb_responses if isinstance(tmdb_responses, list) else []:
            if isinstance(tr, dict) and tr.get("id") == rid:
                response_row = tr
                break

    # Record this read invocation into tool_requests stream per business rule (best-effort, uses existing enum tool)
    # Treat as a cached "hit" if the referenced response exists and is fresh and not expired.
    cache_mode = "bypass"
    response_id = None
    if response_row and response_row.get("status") == "fresh":
        # check expiry if present
        exp = response_row.get("expires_at")
        try:
            exp_dt = None
            if isinstance(exp, str):
                exp_dt = datetime.datetime.fromisoformat(exp.replace("Z", "+00:00"))
                if exp_dt.tzinfo is None:
                    exp_dt = exp_dt.replace(tzinfo=datetime.timezone.utc)
            if exp_dt is None or now < exp_dt:
                cache_mode = "hit"
                response_id = response_row.get("id")
            else:
                cache_mode = "miss"
        except Exception:
            cache_mode = "hit"
            response_id = response_row.get("id")

    req_row = {
        "id": _gen_id("tmdb_req_"),
        "api_key_id": api_key_row.get("id"),
        "tool_name": "search_movies",
        "parameters": {},
        "status": "succeeded",
        "http_status": 200,
        "error_code": None,
        "error_message": None,
        "cache_mode": cache_mode,
        "response_id": response_id,
        "started_at": _iso(now),
        "completed_at": _iso(now),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    try:
        tool_requests.append(req_row)
        _save("tool_requests.json", tool_requests)
        # last_used_at update
        api_key_row["last_used_at"] = _iso(now)
        api_key_row["updated_at"] = _iso(now)
        _save("api_keys.json", api_keys)
    except Exception:
        pass

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "tool_request": tool_req_row,
        "linked_response": response_row,
        "latency_ms": latency_ms,
    }

def list_tmdb_responses(api_key, tool_name=None, cache_key=None, status=None, fetched_from=None, fetched_to=None, include_response_json=None, page=None, page_size=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0236000" if __import__("os").path.isdir("./environment_mix/0236000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            if s.tzinfo is None:
                return s.replace(tzinfo=datetime.timezone.utc)
            return s.astimezone(datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            s2 = s.strip()
            if s2.endswith("Z"):
                s2 = s2[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _hash_key_material(raw):
        return hashlib.sha256(raw.encode("utf-8")).hexdigest()

    def _bucket_start(dt, bucket_type):
        if bucket_type == "minute":
            return dt.replace(second=0, microsecond=0)
        if bucket_type == "day":
            return dt.replace(hour=0, minute=0, second=0, microsecond=0)
        return None

    def _get_usage_count(usage_rows, api_key_row, dt, bucket_type):
        bs = _bucket_start(dt, bucket_type).isoformat()
        for r in usage_rows:
            if r.get("api_key_id") == api_key_row["id"] and r.get("bucket_type") == bucket_type and r.get("bucket_start") == bs:
                try:
                    return int(r.get("request_count", 0))
                except Exception:
                    return 0
        return 0

    def _upsert_usage(usage_rows, api_key_row, dt, bucket_type):
        bs = _bucket_start(dt, bucket_type).isoformat()
        for r in usage_rows:
            if r.get("api_key_id") == api_key_row["id"] and r.get("bucket_type") == bucket_type and r.get("bucket_start") == bs:
                r["request_count"] = int(r.get("request_count", 0)) + 1
                r["last_request_at"] = dt.isoformat()
                r["updated_at"] = _now_iso()
                return
        usage_rows.append({
            "id": f"usage_{hashlib.sha256((str(time.time_ns()) + os.urandom(8).hex()).encode()).hexdigest()[:24]}",
            "api_key_id": api_key_row["id"],
            "bucket_type": bucket_type,
            "bucket_start": bs,
            "request_count": 1,
            "last_request_at": dt.isoformat(),
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        })

    t0 = time.perf_counter()
    now = datetime.datetime.now(datetime.timezone.utc)

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    if include_response_json is None:
        include_response_json = False
    if not isinstance(include_response_json, bool):
        return _err("VALIDATION_ERROR", "include_response_json must be a boolean")

    if page is None:
        page = 1
    if page_size is None:
        page_size = 25

    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        return _err("VALIDATION_ERROR", "page_size must be an integer in [1,100]")

    if tool_name is not None:
        if not isinstance(tool_name, str):
            return _err("VALIDATION_ERROR", "tool_name must be a string")
        if tool_name not in ("search_movies", "get_recommendations", "get_trending"):
            return _err("VALIDATION_ERROR", "Invalid tool_name")

    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("fresh", "stale", "purged"):
            return _err("VALIDATION_ERROR", "Invalid status")

    if cache_key is not None and (not isinstance(cache_key, str) or not cache_key.strip()):
        return _err("VALIDATION_ERROR", "cache_key must be a non-empty string when provided")

    dt_from = _parse_dt(fetched_from)
    if fetched_from is not None and dt_from is None:
        return _err("VALIDATION_ERROR", "fetched_from must be an ISO 8601 date-time string")
    dt_to = _parse_dt(fetched_to)
    if fetched_to is not None and dt_to is None:
        return _err("VALIDATION_ERROR", "fetched_to must be an ISO 8601 date-time string")
    if dt_from and dt_to and dt_to < dt_from:
        return _err("VALIDATION_ERROR", "fetched_to must be >= fetched_from")

    api_keys = _load("api_keys.json")
    usage = _load("api_key_usage_buckets.json")
    responses = _load("tmdb_responses.json")

    key_hash = hashlib.sha256(api_key.strip().encode("utf-8")).hexdigest()
    authed = None
    for k in api_keys:
        if k.get("id") == api_key or k.get("key_hash") == key_hash:
            authed = k
            break
    if authed is None:
        return _err("UNAUTHORIZED", "Invalid API key")
    if authed.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active", http_status=403)

    try:
        per_min = int(authed.get("quota_requests_per_minute", 0))
        per_day = int(authed.get("quota_requests_per_day", 0))
    except Exception:
        return _err("VALIDATION_ERROR", "API key quota fields are invalid")

    minute_count = _get_usage_count(usage, authed, now, "minute")
    day_count = _get_usage_count(usage, authed, now, "day")
    if (minute_count + 1) > per_min:
        return _err("RATE_LIMIT", "Per-minute request quota exceeded", limit=per_min)
    if (day_count + 1) > per_day:
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", limit=per_day)

    _upsert_usage(usage, authed, now, "minute")
    _upsert_usage(usage, authed, now, "day")
    authed["last_used_at"] = now.isoformat()
    authed["updated_at"] = _now_iso()
    _save("api_key_usage_buckets.json", usage)
    _save("api_keys.json", api_keys)

    # TTL policy: if expires_at exists and now >= expires_at, mark as stale (fresh -> stale).
    changed = False
    for r in responses:
        if r.get("status") == "fresh":
            exp = _parse_dt(r.get("expires_at"))
            if exp is not None and now >= exp:
                r["status"] = "stale"
                r["updated_at"] = _now_iso()
                changed = True
    if changed:
        _save("tmdb_responses.json", responses)

    # Filter
    def _matches(r):
        if tool_name is not None and r.get("tool_name") != tool_name:
            return False
        if cache_key is not None and r.get("cache_key") != cache_key:
            return False
        if status is not None and r.get("status") != status:
            return False
        fa = _parse_dt(r.get("fetched_at"))
        if dt_from is not None:
            if fa is None or fa < dt_from:
                return False
        if dt_to is not None:
            if fa is None or fa > dt_to:
                return False
        return True

    filtered = [r for r in responses if _matches(r)]

    # Sort by fetched_at desc, then id
    def _sort_key(r):
        fa = _parse_dt(r.get("fetched_at"))
        ts = fa.timestamp() if fa else -1.0
        return (-ts, str(r.get("id", "")))

    filtered.sort(key=_sort_key)

    total = len(filtered)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = filtered[start:end]
    has_more = end < total

    # Omit response_json by default
    out_rows = []
    for r in page_rows:
        if include_response_json:
            out_rows.append(r)
        else:
            rr = dict(r)
            if "response_json" in rr:
                rr.pop("response_json", None)
            out_rows.append(rr)

    latency_ms = int((time.perf_counter() - t0) * 1000)
    return {
        "tmdb_responses": out_rows,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "next_page": (page + 1) if has_more else None,
            "api_key_id": authed["id"],
            "latency_ms": latency_ms,
            "timestamp": now.isoformat(),
        },
    }

