    t0 = time.time()
    now = _utcnow()

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.", latency_ms=int((time.time() - t0) * 1000))
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", latency_ms=int((time.time() - t0) * 1000))
    if status not in ("fresh", "stale", "purged"):
        return _err("VALIDATION_ERROR", "status must be one of: fresh, stale, purged.", latency_ms=int((time.time() - t0) * 1000))
    if null_out_request_links is None:
        null_out_request_links = False
    if not isinstance(null_out_request_links, bool):
        return _err("VALIDATION_ERROR", "null_out_request_links must be a boolean.", latency_ms=int((time.time() - t0) * 1000))

