        return _err("UNAUTHORIZED", "Invalid API key.", latency_ms=int((time.time() - t0) * 1000))

    if api_key_row.get("status") != "active":
        reqs = tool_requests if isinstance(tool_requests, list) else []
        reqs.append({
            "id": _gen_id("tmdb_req_"),
            "api_key_id": api_key_row.get("id"),
            "tool_name": "search_movies",
            "parameters": {},
            "status": "failed",
            "http_status": 403,
            "error_code": "KEY_FORBIDDEN",
            "error_message": "API key is not active.",
            "cache_mode": "bypass",
            "response_id": None,
            "started_at": _iso(now),
            "completed_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        try:
            _save("tool_requests.json", reqs)
        except Exception:
            pass
        return _err("UNAUTHORIZED", "API key is not active.", latency_ms=int((time.time() - t0) * 1000))

    # Find response by id
    resp = None
    idx = None
    if isinstance(tmdb_responses, list):
        for i, r in enumerate(tmdb_responses):
            if isinstance(r, dict) and r.get("id") == id:
                resp = r
                idx = i
                break
    if resp is None:
        # record failed call
        reqs = tool_requests if isinstance(tool_requests, list) else []
        reqs.append({
            "id": _gen_id("tmdb_req_"),
            "api_key_id": api_key_row.get("id"),
            "tool_name": "search_movies",
            "parameters": {},
            "status": "failed",
            "http_status": 404,
            "error_code": "NOT_FOUND",
            "error_message": "tmdb_response not found.",
            "cache_mode": "bypass",
            "response_id": None,
            "started_at": _iso(now),
            "completed_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        try:
            _save("tool_requests.json", reqs)
        except Exception:
            pass
        return _err("NOT_FOUND", "tmdb_response not found.", latency_ms=int((time.time() - t0) * 1000))

    current = resp.get("status")
    allowed = {
        "fresh": ("stale", "purged"),
        "stale": ("fresh", "purged"),
        "purged": tuple(),
    }

    if current not in allowed:
        # defensive: invalid stored value
        reqs = tool_requests if isinstance(tool_requests, list) else []
        reqs.append({
            "id": _gen_id("tmdb_req_"),
            "api_key_id": api_key_row.get("id"),
            "tool_name": "search_movies",
            "parameters": {},
            "status": "failed",
            "http_status": 409,
            "error_code": "INVALID_TRANSITION",
            "error_message": "Cached response has an invalid current status; cannot transition.",
            "cache_mode": "bypass",
            "response_id": None,
            "started_at": _iso(now),
            "completed_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        try:
            _save("tool_requests.json", reqs)
        except Exception:
            pass
        return _err("INVALID_TRANSITION", "Cached response has an invalid current status; cannot transition.", latency_ms=int((time.time() - t0) * 1000))

    # Idempotent if same status
    if status == current:
        api_key_row["last_used_at"] = _iso(now)
        api_key_row["updated_at"] = _iso(now)
        try:
            _save("api_keys.json", api_keys)
        except Exception:
            pass

        # record succeeded call
        reqs = tool_requests if isinstance(tool_requests, list) else []
        reqs.append({
            "id": _gen_id("tmdb_req_"),
            "api_key_id": api_key_row.get("id"),
            "tool_name": "search_movies",
            "parameters": {},
            "status": "succeeded",
            "http_status": 200,
            "error_code": None,
            "error_message": None,
            "cache_mode": "bypass",
            "response_id": resp.get("id"),
            "started_at": _iso(now),
            "completed_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        try:
            _save("tool_requests.json", reqs)
        except Exception:
            pass

        return {"tmdb_response": resp, "latency_ms": int((time.time() - t0) * 1000), "idempotent": True}

    # Enforce lifecycle transitions; no transitions out of purged
    if current == "purged":
        reqs = tool_requests if isinstance(tool_requests, list) else []
        reqs.append({
            "id": _gen_id("tmdb_req_"),
            "api_key_id": api_key_row.get("id"),
            "tool_name": "search_movies",
            "parameters": {},
            "status": "failed",
            "http_status": 409,
            "error_code": "INVALID_TRANSITION",
            "error_message": "Cannot modify a purged cache entry (no transitions out of purged).",
            "cache_mode": "bypass",
            "response_id": resp.get("id"),
            "started_at": _iso(now),
            "completed_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        try:
            _save("tool_requests.json", reqs)
        except Exception:
            pass
        return _err("INVALID_TRANSITION", "Cannot modify a purged cache entry (no transitions out of purged).", latency_ms=int((time.time() - t0) * 1000))

    if status not in allowed.get(current, ()):
        reqs = tool_requests if isinstance(tool_requests, list) else []
        reqs.append({
            "id": _gen_id("tmdb_req_"),
            "api_key_id": api_key_row.get("id"),
            "tool_name": "search_movies",
            "parameters": {},
            "status": "failed",
            "http_status": 409,
            "error_code": "INVALID_TRANSITION",
            "error_message": f"Invalid transition {current} -> {status}. Allowed: {list(allowed.get(current, ())) }.",
            "cache_mode": "bypass",
            "response_id": resp.get("id"),
            "started_at": _iso(now),
            "completed_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        try:
            _save("tool_requests.json", reqs)
        except Exception:
            pass
        return _err("INVALID_TRANSITION", f"Invalid transition {current} -> {status}.", allowed=list(allowed.get(current, ())), latency_ms=int((time.time() - t0) * 1000))

    # Apply transition
    resp["status"] = status
    resp["updated_at"] = _iso(now)
    # If marking fresh, ensure fetched_at exists (do not fabricate; keep as-is if present)
    if status == "purged":
        # keep row for FK history, but payload access is effectively removed: clear response_json
        resp["response_json"] = {}  # still a JSON object per constraint
        resp["movie_tmdb_ids"] = resp.get("movie_tmdb_ids", None)
        # optionally null out links from tool_requests
        if null_out_request_links and isinstance(tool_requests, list):
            changed = False
            for tr in tool_requests:
                if isinstance(tr, dict) and tr.get("response_id") == resp.get("id"):
                    tr["response_id"] = None
                    tr["updated_at"] = _iso(now)
                    changed = True
            if changed:
                try:
                    _save("tool_requests.json", tool_requests)
                except Exception:
                    pass

    # Persist response change
    tmdb_responses[idx] = resp
    try:
        _save("tmdb_responses.json", tmdb_responses)
    except Exception:
        return _err("CONFLICT", "Failed to persist cache status update.", latency_ms=int((time.time() - t0) * 1000))

    # Update api_keys last_used
    api_key_row["last_used_at"] = _iso(now)
    api_key_row["updated_at"] = _iso(now)
    try:
        _save("api_keys.json", api_keys)
    except Exception:
        pass

    # Record succeeded tool_request (best-effort: use existing enum tool)
    reqs = tool_requests if isinstance(tool_requests, list) else []
    reqs.append({
        "id": _gen_id("tmdb_req_"),
        "api_key_id": api_key_row.get("id"),
        "tool_name": "search_movies",
        "parameters": {},
        "status": "succeeded",
        "http_status": 200,
        "error_code": None,
        "error_message": None,
        "cache_mode": "bypass",
        "response_id": resp.get("id") if status != "purged" else (None if null_out_request_links else resp.get("id")),
        "started_at": _iso(now),
        "completed_at": _iso(now),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    })
    try:
        _save("tool_requests.json", reqs)
    except Exception:
        pass

    return {
        "tmdb_response": resp,
        "latency_ms": int((time.time() - t0) * 1000),
        "transition": {"from": current, "to": status},
    }

def create_api_key(admin_api_key, label, plan, quota_requests_per_day, quota_requests_per_minute, status=None, **_extra):
    import json, os, datetime, time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0236000" if __import__("os").path.isdir("./environment_mix/0236000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _hash_key_material(raw):
        return hashlib.sha256(raw.encode("utf-8")).hexdigest()

    def _gen_id(prefix):
        return f"{prefix}_{hashlib.sha256((str(time.time_ns()) + '_' + os.urandom(8).hex()).encode('utf-8')).hexdigest()[:24]}"

    # Validate inputs
    if not isinstance(admin_api_key, str) or not admin_api_key.strip():
        return _err("VALIDATION_ERROR", "admin_api_key must be a non-empty string")
    if not isinstance(label, str) or not label.strip():
        return _err("VALIDATION_ERROR", "label must be a non-empty string")
    if not isinstance(plan, str) or plan not in ("free", "pro", "enterprise"):
        return _err("VALIDATION_ERROR", "plan must be one of: free, pro, enterprise")
    if not isinstance(quota_requests_per_day, int) or quota_requests_per_day < 0:
        return _err("VALIDATION_ERROR", "quota_requests_per_day must be an integer >= 0")
    if not isinstance(quota_requests_per_minute, int) or quota_requests_per_minute < 0:
        return _err("VALIDATION_ERROR", "quota_requests_per_minute must be an integer >= 0")
    if status is None:
        status = "active"
    if not isinstance(status, str) or status not in ("active", "suspended"):
        return _err("VALIDATION_ERROR", "status must be one of: active, suspended")

    api_keys = _load("api_keys.json")

    # Authorize: require an existing ACTIVE api_keys row with plan='internal' matching admin_api_key (id or hash).
    admin_hash = _hash_key_material(admin_api_key.strip())
    admin_row = None
    for k in api_keys:
        if (k.get("id") == admin_api_key or k.get("key_hash") == admin_hash) and k.get("status") == "active" and k.get("plan") == "internal":
            admin_row = k
            break
    if admin_row is None:
        return _err("UNAUTHORIZED", "Admin authorization failed")

    # Map enterprise -> internal schema plan; enforce schema enum
    stored_plan = plan
    if plan == "enterprise":
        stored_plan = "pro"

    # Generate raw API key (only time shown)
    raw_key = "tmdb_" + secrets.token_urlsafe(24)
    key_hash = _hash_key_material(raw_key)

    # Enforce unique(key_hash)
    for k in api_keys:
        if k.get("key_hash") == key_hash:
            return _err("CONFLICT", "Generated API key collided; retry")

    now = _now_iso()
    new_row = {
        "id": _gen_id("key"),
        "key_hash": key_hash,
        "label": label.strip(),
        "status": status,
        "plan": stored_plan if stored_plan in ("free", "pro", "internal") else "free",
        "quota_requests_per_day": int(quota_requests_per_day),
        "quota_requests_per_minute": int(quota_requests_per_minute),
        "created_at": now,
        "updated_at": now,
        "last_used_at": None,
    }

    api_keys.append(new_row)
    _save("api_keys.json", api_keys)

    # Return created metadata + raw key once
    return {
        "api_key": new_row,
        "raw_api_key": raw_key,
        "meta": {
            "created_by_api_key_id": admin_row["id"],
            "timestamp": now,
        },
    }

def get_whoami(api_key, **_extra):
    import json, os, datetime, hashlib, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0236000" if __import__("os").path.isdir("./environment_mix/0236000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            if v.tzinfo is None:
                v = v.replace(tzinfo=datetime.timezone.utc)
            return v
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _gen_id(prefix):
        return f"{prefix}_{hashlib.sha256((str(time.time_ns()) + prefix).encode('utf-8')).hexdigest()[:24]}"

    def _truncate_minute(dt):
        return dt.replace(second=0, microsecond=0)

    def _truncate_day(dt):
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    # -------- Validate inputs --------
    if api_key is None or not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string")

    api_key = api_key.strip()

    # -------- Load datastore --------
    api_keys = _load("api_keys.json")
    tool_requests = _load("tool_requests.json")
    usage = _load("api_key_usage_buckets.json")

    now = _now_utc()
    started = now
    req_id = _gen_id("treq")

    # Authenticate API key: match by id OR by client-visible value in key_hash (not by hashing).
    key_row = None
    for r in api_keys:
        if isinstance(r, dict) and (r.get("id") == api_key or r.get("key_hash") == api_key):
            key_row = r
            break

    # Create tool_requests row (always), reflecting vendor rule set; parameters are {} for this surface.
    req_row = {
        "id": req_id,
        "api_key_id": key_row.get("id") if isinstance(key_row, dict) else None,
        "tool_name": "get_whoami",  # not in enum list, but must log every invocation for this tool.
        "parameters": {},
        "status": "received",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "cache_mode": "bypass",
        "response_id": None,
        "started_at": None,
        "completed_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    tool_requests.append(req_row)

    def _finalize_failure(http_status, code, message):
        completed = _now_utc()
        req_row["status"] = "failed"
        req_row["http_status"] = int(http_status)
        req_row["error_code"] = code
        req_row["error_message"] = message
        req_row["started_at"] = _iso(started)
        req_row["completed_at"] = _iso(completed)
        req_row["updated_at"] = _iso(completed)
        _save("tool_requests.json", tool_requests)
        return _err(code, message, http_status=int(http_status), request_id=req_id)

    def _finalize_success(body):
        completed = _now_utc()
        req_row["status"] = "succeeded"
        req_row["http_status"] = 200
        req_row["error_code"] = None
        req_row["error_message"] = None
        req_row["started_at"] = _iso(started)
        req_row["completed_at"] = _iso(completed)
        req_row["updated_at"] = _iso(completed)
        _save("tool_requests.json", tool_requests)
        return {
            "request_id": req_id,
            "data": body,
        }

    # Transition to processing
    req_row["status"] = "processing"
    req_row["started_at"] = _iso(started)
    req_row["updated_at"] = _iso(started)
    _save("tool_requests.json", tool_requests)

    # -------- Enforce auth requirements --------
    if key_row is None:
        return _finalize_failure(401, "UNAUTHORIZED", "API key is missing or invalid")

    status = key_row.get("status")
    if status not in ("active", "suspended", "revoked"):
        return _finalize_failure(401, "UNAUTHORIZED", "API key is invalid")

    if status != "active":
        # 403 for suspended/revoked
        return _finalize_failure(403, "UNAUTHORIZED", f"API key is {status}")

    # -------- Rate/quota accounting (read-only for whoami; still counted as a request) --------
    # Upsert minute/day bucket and reject if exceeding.
    quota_min = key_row.get("quota_requests_per_minute")
    quota_day = key_row.get("quota_requests_per_day")
    if not isinstance(quota_min, int) or quota_min < 0:
        return _finalize_failure(500, "VALIDATION_ERROR", "Server misconfiguration: invalid quota_requests_per_minute")
    if not isinstance(quota_day, int) or quota_day < 0:
        return _finalize_failure(500, "VALIDATION_ERROR", "Server misconfiguration: invalid quota_requests_per_day")

    key_id = key_row.get("id")
    if not isinstance(key_id, str) or not key_id:
        return _finalize_failure(500, "VALIDATION_ERROR", "Server misconfiguration: api_keys.id invalid")

    minute_start = _truncate_minute(now)
    day_start = _truncate_day(now)

    def _find_bucket(bucket_type, bucket_start_dt):
        bucket_start_iso = _iso(bucket_start_dt)
        for b in usage:
            if not isinstance(b, dict):
                continue
            if b.get("api_key_id") == key_id and b.get("bucket_type") == bucket_type and b.get("bucket_start") == bucket_start_iso:
                return b
        return None

    minute_bucket = _find_bucket("minute", minute_start)
    day_bucket = _find_bucket("day", day_start)

    def _ensure_bucket(bucket_type, bucket_start_dt):
        b = _find_bucket(bucket_type, bucket_start_dt)
        if b is not None:
            return b, False
        created = _now_utc()
        nb = {
            "id": _gen_id("ubkt"),
            "api_key_id": key_id,
            "bucket_type": bucket_type,
            "bucket_start": _iso(bucket_start_dt),
            "request_count": 0,
            "last_request_at": None,
            "created_at": _iso(created),
            "updated_at": _iso(created),
        }
        usage.append(nb)
        return nb, True

    minute_bucket, _ = _ensure_bucket("minute", minute_start)
    day_bucket, _ = _ensure_bucket("day", day_start)

    # Validate existing counts
    mc = minute_bucket.get("request_count")
    dc = day_bucket.get("request_count")
    if not isinstance(mc, int) or mc < 0 or not isinstance(dc, int) or dc < 0:
        return _finalize_failure(500, "VALIDATION_ERROR", "Server misconfiguration: invalid usage bucket counts")

    # Would exceed?
    if quota_min >= 0 and (mc + 1) > quota_min:
        # Persist request row already; do not increment buckets.
        _save("api_key_usage_buckets.json", usage)
        return _finalize_failure(429, "RATE_LIMIT", "Rate limit exceeded (per-minute quota)")

    if quota_day >= 0 and (dc + 1) > quota_day:
        _save("api_key_usage_buckets.json", usage)
        return _finalize_failure(429, "QUOTA_EXCEEDED", "Quota exceeded (per-day quota)")

    # Apply increments
    minute_bucket["request_count"] = mc + 1
    minute_bucket["last_request_at"] = _iso(now)
    minute_bucket["updated_at"] = _iso(now)

    day_bucket["request_count"] = dc + 1
    day_bucket["last_request_at"] = _iso(now)
    day_bucket["updated_at"] = _iso(now)

    # Update key last_used_at
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)

    _save("api_key_usage_buckets.json", usage)
    _save("api_keys.json", api_keys)

    # -------- Build response --------
    body = {
        "api_key_id": key_id,
        "label": key_row.get("label"),
        "status": status,
        "plan": key_row.get("plan"),
        "effective_scopes": ["read"],  # vendor surface here is read-only tools
        "quotas": {
            "requests_per_minute": quota_min,
            "requests_per_day": quota_day,
        },
        "usage": {
            "minute": {
                "bucket_start": minute_bucket.get("bucket_start"),
                "request_count": minute_bucket.get("request_count"),
                "remaining": max(0, quota_min - int(minute_bucket.get("request_count") or 0)),
                "last_request_at": minute_bucket.get("last_request_at"),
            },
            "day": {
                "bucket_start": day_bucket.get("bucket_start"),
                "request_count": day_bucket.get("request_count"),
                "remaining": max(0, quota_day - int(day_bucket.get("request_count") or 0)),
                "last_request_at": day_bucket.get("last_request_at"),
            },
        },
        "timestamps": {
            "created_at": key_row.get("created_at"),
            "updated_at": key_row.get("updated_at"),
            "last_used_at": key_row.get("last_used_at"),
        },
    }

    return _finalize_success(body)
